/* Persian calendar at the UI boundary; database dates remain ISO. */
const AcademyDates=(()=>{const formatter=new Intl.DateTimeFormat('en-US-u-ca-persian',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:'UTC'});const digits=s=>String(s).replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c)).replace(/[٠-٩]/g,c=>'٠١٢٣٤٥٦٧٨٩'.indexOf(c));function parts(iso){const d=new Date(iso.slice(0,10)+'T12:00:00Z');if(isNaN(d))throw Error('تاریخ معتبر نیست');const p=Object.fromEntries(formatter.formatToParts(d).map(p=>[p.type,p.value]));return [+p.year,+p.month,+p.day]}function show(iso){if(!iso)return '—';try{return parts(iso).map((v,i)=>i?String(v).padStart(2,'0'):v).join('/').replace(/\d/g,c=>'۰۱۲۳۴۵۶۷۸۹'[c])}catch{return '—'}}function iso(value){let v=digits(value).trim();if(/^\d{4}-\d{2}-\d{2}$/.test(v)&&+v.slice(0,4)>1700)return v;const m=v.match(/^(\d{4})[\/.-](\d{1,2})[\/.-](\d{1,2})$/);if(!m)throw Error('تاریخ شمسی را مانند ۱۴۰۵/۰۸/۰۱ وارد کنید');const y=+m[1],mo=+m[2],day=+m[3];if(y<1200||y>1600||mo<1||mo>12||day<1||day>31)throw Error('تاریخ شمسی معتبر نیست');let lo=Date.UTC(y+621,0,1),hi=Date.UTC(y+622,11,31),target=y*10000+mo*100+day;while(lo<=hi){const mid=Math.floor((lo/86400000+hi/86400000)/2)*86400000;const s=new Date(mid).toISOString().slice(0,10),p=parts(s),n=p[0]*10000+p[1]*100+p[2];if(n===target)return s;if(n<target)lo=mid+86400000;else hi=mid-86400000}throw Error('این روز در تقویم شمسی وجود ندارد')}function today(){return new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Tehran'})}return {show,iso,today,start:iso('1405/08/01')}})();
/* Assist every date field without requiring a browser's Gregorian picker. */
document.addEventListener('input',e=>{const el=e.target;if(!el.matches('[data-persian-date]'))return;const raw=el.value.replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c)).replace(/[٠-٩]/g,c=>'٠١٢٣٤٥٦٧٨٩'.indexOf(c));if(/^\d{8}$/.test(raw))el.value=raw.slice(0,4)+'/'+raw.slice(4,6)+'/'+raw.slice(6);});
new MutationObserver(()=>{document.querySelectorAll('[data-persian-date]:not([data-date-ready])').forEach(el=>{el.dataset.dateReady='true';const tools=document.createElement('span');tools.style.cssText='display:flex;gap:8px;align-items:center;font-size:12px;margin-top:6px';const hint=document.createElement('small');hint.textContent='سال / ماه / روز؛ اعداد فارسی یا انگلیسی';tools.append(hint);const today=document.createElement('button');today.type='button';today.textContent='امروز';today.style.cssText='padding:4px 12px;font-size:12px';today.onclick=()=>{el.value=AcademyDates.show(AcademyDates.today())};tools.append(today);el.after(tools);});}).observe(document.documentElement,{childList:true,subtree:true});
